window.LEARN = window.LEARN || {};

/* نصوص قراءة متدرّجة (المجموعة ب): gl مفردات مساعدة؛ q [سؤال، خيارات، رقم الصحيح] */
LEARN.READ = (LEARN.READ || []).concat([
  /* ---------- A1 ---------- */
  { id: "r30", lv: "A1", t: "Un día normal", tar: "يوم عادي", text: "Me llamo Yusuf y vivo en Madrid. Todos los días me levanto a las seis y media. Primero rezo y después desayuno pan con aceite y un vaso de leche. Voy al trabajo en metro. Trabajo en una tienda de ropa desde las nueve hasta las cinco. A las dos como con mis compañeros. Por la tarde vuelvo a casa, hago deporte y ceno con mi familia. Antes de dormir leo un poco. Los sábados no trabajo y visito a mis amigos.", gl: ["levantarse|ينهض من الفراش", "desayunar|يتناول الفطور", "la tienda de ropa|محلّ الملابس", "el compañero|الزميل", "volver|يعود", "antes de|قبل"], q: [["¿A qué hora se levanta Yusuf?", ["A las seis y media", "A las nueve", "A las dos"], 0], ["¿Cómo va al trabajo?", ["En autobús", "En metro", "En coche"], 1], ["¿Dónde trabaja?", ["En una escuela", "En un restaurante", "En una tienda de ropa"], 2], ["¿Qué hace antes de dormir?", ["Hace deporte", "Lee un poco", "Cena"], 1], ["¿Qué hace los sábados?", ["Trabaja", "Va al metro", "Visita a sus amigos"], 2]] },

  { id: "r31", lv: "A1", t: "En el mercado", tar: "في السوق", text: "Hoy es sábado y Lucía va al mercado con su madre. Viven en Puebla, en México. En el mercado hay muchas frutas: mangos, plátanos, naranjas y papayas. También hay verduras, pan y flores. La madre de Lucía compra un kilo de tomates y dos aguacates. Lucía quiere un jugo de naranja. El señor del puesto es muy amable y le regala una fruta. Después, las dos toman un chocolate caliente y vuelven a casa caminando. A Lucía le gusta mucho el mercado porque tiene muchos colores.", gl: ["el mercado|السوق", "la fruta|الفاكهة", "el aguacate|الأفوكادو", "el jugo|العصير", "el puesto|البسطة / كشك البيع", "amable|لطيف", "regalar|يُهدي"], q: [["¿Con quién va Lucía al mercado?", ["Con su padre", "Con su madre", "Con su hermana"], 1], ["¿Qué compra la madre?", ["Tomates y aguacates", "Mangos y papayas", "Pan y flores"], 0], ["¿Qué quiere Lucía?", ["Un chocolate", "Una papaya", "Un jugo de naranja"], 2], ["¿Qué le regala el señor del puesto?", ["Una flor", "Un pan", "Una fruta"], 2], ["¿Por qué le gusta el mercado a Lucía?", ["Porque es grande", "Porque tiene muchos colores", "Porque está cerca"], 1]] },

  { id: "r32", lv: "A1", t: "El trabajo de mi padre", tar: "عمل أبي", text: "Mi padre se llama Omar y es panadero. Trabaja en una panadería pequeña. Se levanta temprano, a las cuatro de la mañana, porque el pan tiene que estar listo a las siete. Hace pan, bollos y galletas. Su trabajo es duro, pero le gusta. Dice que el olor del pan caliente es el mejor. Los clientes son sus vecinos y todos lo conocen. A las dos de la tarde termina y vuelve a casa para comer con nosotros. Por la tarde descansa. Yo quiero ser panadero como él.", gl: ["el panadero|الخبّاز", "temprano|مبكّرًا", "listo|جاهز", "el bollo|الكعكة الصغيرة", "duro|شاقّ", "el olor|الرائحة", "el cliente|الزبون"], q: [["¿Qué es Omar?", ["Médico", "Panadero", "Taxista"], 1], ["¿A qué hora se levanta?", ["A las siete", "A las dos", "A las cuatro"], 2], ["¿Qué hace en la panadería?", ["Pan, bollos y galletas", "Solo pan", "Pasteles de boda"], 0], ["¿Quiénes son los clientes?", ["Turistas", "Sus vecinos", "Estudiantes"], 1], ["¿Qué hace por la tarde?", ["Trabaja", "Estudia", "Descansa"], 2]] },

  { id: "r33", lv: "A1", t: "Un viaje en tren", tar: "رحلة بالقطار", text: "Mañana Amina y su familia viajan a Barcelona en tren. El tren sale de Sevilla a las ocho de la mañana y llega a las dos de la tarde. Amina prepara su mochila: lleva un libro, agua, fruta y su cámara. Su hermano pequeño lleva un juego. En Barcelona van a visitar a los tíos y a ver el mar. También quieren pasear por la ciudad y comer paella de pescado. Amina está muy contenta porque es su primer viaje en tren. Esta noche no puede dormir.", gl: ["viajar|يسافر", "salir|ينطلق / يغادر", "llegar|يصل", "la mochila|حقيبة الظهر", "la cámara|آلة التصوير", "los tíos|العمّ وزوجته أو الخال وزوجته", "contento|مسرور"], q: [["¿Adónde viaja la familia?", ["A Sevilla", "A Barcelona", "A Madrid"], 1], ["¿A qué hora sale el tren?", ["A las dos", "A las ocho de la noche", "A las ocho de la mañana"], 2], ["¿Qué lleva Amina en la mochila?", ["Un juego", "Un libro, agua, fruta y su cámara", "Ropa de deporte"], 1], ["¿A quién van a visitar?", ["A los abuelos", "A unos amigos", "A los tíos"], 2], ["¿Por qué está contenta Amina?", ["Porque es su primer viaje en tren", "Porque no tiene clase", "Porque va a nadar"], 0]] },

  /* ---------- A2 ---------- */
  { id: "r34", lv: "A2", t: "El Ramadán de la familia Haddad", tar: "رمضان عائلة حدّاد", text: "La familia Haddad vive en Valencia. En Ramadán, su día cambia un poco. La madre, Samira, se levanta a las cinco para preparar el suhur: dátiles, yogur, pan y té. Toda la familia come junta antes del amanecer y después rezan. El padre, Nabil, va a trabajar como siempre, y los niños van al colegio. Por la tarde, la casa huele a sopa de lentejas y a pan recién hecho. Los niños ayudan a poner la mesa. Cuando se pone el sol, rompen el ayuno con agua y dátiles, y luego cenan tranquilamente. Por la noche, Nabil y su hijo mayor van a la mezquita. Antes de dormir, Samira lee un poco del Corán. Es un mes de paciencia, pero también de alegría y de familia.", gl: ["el amanecer|الفجر", "oler a|تفوح منه رائحة", "recién hecho|طازج أُعدّ للتوّ", "poner la mesa|يُعدّ المائدة", "ponerse el sol|تغرب الشمس", "romper el ayuno|يُفطر", "la alegría|الفرح"], q: [["¿A qué hora se levanta Samira?", ["A las cinco", "A las siete", "A las cuatro"], 0], ["¿Qué hace Nabil durante el día?", ["Se queda en casa", "Va a trabajar", "Va a la mezquita"], 1], ["¿Con qué rompen el ayuno?", ["Con sopa de lentejas", "Con pan y té", "Con agua y dátiles"], 2], ["¿Quién va a la mezquita por la noche?", ["Samira y los niños", "Nabil y su hijo mayor", "Toda la familia"], 1], ["¿Cómo describe el texto el mes de Ramadán?", ["Como un mes difícil y triste", "Como un mes de vacaciones", "Como un mes de paciencia y alegría"], 2]] },

  { id: "r35", lv: "A2", t: "Un correo desde Lima", tar: "رسالة إلكترونية من ليما", text: "Asunto: ¡Noticias desde Lima! Hola, Marta: ¿Qué tal estás? Te escribo desde Lima, donde llevo ya dos semanas por trabajo. La ciudad es enorme y el tráfico es terrible, pero la gente es muy amable. Los fines de semana paseo por el centro histórico y por el barrio de Barranco, que tiene vistas al mar. Lo que más me gusta es la comida: ayer probé una sopa de quinua deliciosa. Todavía no he visitado Cusco, pero quiero ir el mes que viene. El trabajo va bien, aunque las reuniones son largas y termino cansado. ¿Y tú? ¿Cómo va el nuevo curso? Escríbeme cuando puedas y cuéntame todo. Saluda a tu familia de mi parte. Un abrazo fuerte, Rafael", gl: ["el asunto|موضوع الرسالة", "llevar dos semanas|منذ أسبوعين", "el tráfico|حركة المرور", "probar|يتذوّق / يجرّب", "la reunión|الاجتماع", "de mi parte|من طرفي", "un abrazo|تحية ختامية ودّية"], q: [["¿Desde dónde escribe Rafael?", ["Desde Cusco", "Desde Lima", "Desde Barranco"], 1], ["¿Cuánto tiempo lleva allí?", ["Dos días", "Dos meses", "Dos semanas"], 2], ["¿Qué es lo que más le gusta?", ["La comida", "El tráfico", "Las reuniones"], 0], ["¿Qué quiere hacer el mes que viene?", ["Volver a casa", "Visitar Cusco", "Cambiar de trabajo"], 1], ["¿Qué le pide a Marta?", ["Que le envíe dinero", "Que viaje a Lima", "Que le escriba y le cuente todo"], 2]] },

  { id: "r36", lv: "A2", t: "En el centro de salud", tar: "في المركز الصحي", text: "Desde hace tres días, Hasan tiene dolor de garganta y un poco de fiebre. Esta mañana ha pedido cita en el centro de salud de su barrio. En la sala de espera hay mucha gente: una señora con un bebé, un chico con el brazo vendado y un hombre que tose sin parar. Después de veinte minutos, la doctora López lo llama. Le mira la garganta, le toma la temperatura y le pregunta si es alérgico a algún medicamento. «No es nada grave», le dice. «Tiene una infección leve. Tome este jarabe tres veces al día, beba mucha agua y descanse». También le recomienda no ir al trabajo durante dos días. Hasan sale más tranquilo y pasa por la farmacia. Esa noche, por fin, duerme bien.", gl: ["el dolor de garganta|ألم الحلق", "la fiebre|الحمّى", "pedir cita|يحجز موعدًا", "la sala de espera|غرفة الانتظار", "vendado|مُضمَّد", "toser|يسعل", "el jarabe|شراب الدواء", "leve|خفيف"], q: [["¿Qué le pasa a Hasan?", ["Le duele la garganta y tiene fiebre", "Tiene el brazo roto", "Le duele el estómago"], 0], ["¿Quién lo atiende?", ["Un enfermero", "La doctora López", "El farmacéutico"], 1], ["¿Cuántas veces al día tiene que tomar el jarabe?", ["Una", "Dos", "Tres"], 2], ["¿Qué le recomienda la doctora?", ["Hacer deporte", "Descansar y beber agua", "Ir al hospital"], 1], ["¿Adónde va Hasan después?", ["Al trabajo", "A casa de un amigo", "A la farmacia"], 2]] },

  { id: "r37", lv: "A2", t: "Un domingo en Bogotá", tar: "يوم أحد في بوغوتا", text: "Carolina vive en Bogotá, la capital de Colombia, una ciudad que está a más de dos mil quinientos metros de altura. Por eso, las mañanas son frescas aunque esté cerca del ecuador. Los domingos, la ciudad cierra muchas avenidas a los coches y miles de personas salen a montar en bicicleta, a correr o a pasear con sus perros. Carolina va con su primo Andrés. Recorren varios kilómetros y luego desayunan arepas con queso y chocolate caliente en un puesto de la calle. Después visitan a la abuela, que vive en el barrio de La Candelaria, lleno de casas antiguas de colores. Por la tarde, cuando empieza a llover, como casi siempre en Bogotá, vuelven a casa en el autobús. Carolina dice que el domingo es su día favorito.", gl: ["la altura|الارتفاع", "fresco|منعش / بارد قليلًا", "la avenida|الجادّة", "montar en bicicleta|يركب الدرّاجة", "recorrer|يقطع مسافة", "la arepa|الأريبا (خبز الذرة الكولومبي)", "el barrio|الحيّ"], q: [["¿Por qué son frescas las mañanas en Bogotá?", ["Porque está lejos del ecuador", "Porque está a mucha altura", "Porque siempre nieva"], 1], ["¿Qué pasa los domingos en la ciudad?", ["Cierran avenidas para bicicletas y peatones", "Cierran los mercados", "Hay un desfile"], 0], ["¿Con quién va Carolina?", ["Con su abuela", "Con su primo Andrés", "Con su perro"], 1], ["¿Qué desayunan?", ["Pan con aceite", "Fruta y café", "Arepas con queso y chocolate"], 2], ["¿Cómo vuelven a casa?", ["En bicicleta", "Caminando", "En autobús"], 2]] },

  { id: "r38", lv: "A2", t: "Reciclar en casa", tar: "إعادة التدوير في المنزل", text: "Hace un año, la familia Ruiz decidió cambiar algunas costumbres para cuidar el medio ambiente. Primero pusieron tres cubos en la cocina: uno amarillo para el plástico, uno azul para el papel y uno verde para el vidrio. Al principio, los niños se confundían, pero ahora lo hacen sin pensar. También compraron bolsas de tela para ir al supermercado y dejaron de usar botellas de agua de plástico. En el balcón plantaron tomates y hierbas aromáticas. Los fines de semana, en lugar de ir al centro comercial en coche, van al parque en bicicleta. La madre, Elena, dice que ahora gastan menos dinero y producen menos basura. «No es difícil», explica. «Solo hay que empezar con cosas pequeñas». Sus vecinos ya les han pedido consejos.", gl: ["la costumbre|العادة", "el medio ambiente|البيئة", "el cubo|سلّة المهملات", "el vidrio|الزجاج", "confundirse|يختلط عليه الأمر", "la bolsa de tela|الكيس القماشي", "la basura|القمامة", "el consejo|النصيحة"], q: [["¿Cuántos cubos pusieron en la cocina?", ["Dos", "Tres", "Cuatro"], 1], ["¿De qué color es el cubo del papel?", ["Amarillo", "Verde", "Azul"], 2], ["¿Qué plantaron en el balcón?", ["Flores", "Tomates y hierbas aromáticas", "Naranjos"], 1], ["¿Cómo van al parque los fines de semana?", ["En coche", "En autobús", "En bicicleta"], 2], ["Según Elena, ¿qué hay que hacer?", ["Empezar con cosas pequeñas", "Comprar más cosas", "Mudarse al campo"], 0]] },

  /* ---------- B1 ---------- */
  { id: "r39", lv: "B1", t: "La primera vez en la mezquita", tar: "المرّة الأولى في المسجد", text: "Javier había leído mucho sobre el islam durante casi un año. Hacía preguntas, comparaba, dudaba y volvía a leer. Cuando por fin decidió hacerse musulmán, lo primero que sintió fue paz; lo segundo, nervios: nunca había entrado en una mezquita. Un viernes, su amigo Ismail lo acompañó. Al llegar, se quitaron los zapatos en la entrada y Javier notó la alfombra suave bajo los pies. La sala era sencilla y luminosa, sin imágenes, solo líneas en el suelo y letras árabes en la pared. Varios hombres mayores se acercaron a saludarlo con una sonrisa y le dijeron «bienvenido, hermano». Nadie le preguntó de dónde venía ni por qué estaba allí. Durante el sermón no entendió todas las palabras, pero sintió que formaba parte de algo grande y antiguo. Al salir, un señor le regaló un libro pequeño y le dio su número de teléfono: «Para cualquier duda». Javier volvió a casa caminando despacio. Sabía que iba a volver.", gl: ["dudar|يشكّ / يتردّد", "los nervios|التوتّر", "quitarse los zapatos|يخلع حذاءه", "la alfombra|السجّادة", "luminoso|مُضاء / مشرق", "el sermón|الخطبة", "formar parte de|يكون جزءًا من", "la duda|السؤال أو الشكّ"], q: [["¿Cuánto tiempo había leído Javier sobre el islam?", ["Unas semanas", "Casi un año", "Diez años"], 1], ["¿Quién lo acompañó a la mezquita?", ["Su padre", "Un señor mayor", "Su amigo Ismail"], 2], ["¿Cómo era la sala de oración?", ["Oscura y llena de imágenes", "Sencilla y luminosa", "Pequeña y ruidosa"], 1], ["¿Qué hicieron los hombres mayores?", ["Lo saludaron y le dieron la bienvenida", "Le hicieron muchas preguntas", "Lo ignoraron"], 0], ["¿Qué le regaló un señor al salir?", ["Una alfombra", "Unos zapatos", "Un libro pequeño"], 2], ["¿Cómo volvió Javier a casa?", ["En autobús con prisa", "Caminando despacio", "En coche con Ismail"], 1]] },

  { id: "r40", lv: "B1", t: "La entrevista", tar: "مقابلة العمل", text: "Leila llevaba cuatro meses buscando trabajo. Había enviado más de cincuenta currículums y solo la habían llamado dos veces. Por eso, cuando una empresa de logística la citó para una entrevista, preparó cada detalle: estudió la página web de la empresa, repasó sus respuestas frente al espejo y planchó su mejor blusa. El día de la entrevista llegó veinte minutos antes. La entrevistadora, una mujer de unos cincuenta años llamada Beatriz, fue amable pero directa. Le preguntó por su experiencia, por qué había dejado su último empleo y cómo reaccionaría ante un cliente enfadado. Leila respondió con calma y con ejemplos concretos. Cuando le preguntaron por sus puntos débiles, no dijo «ninguno», sino que reconoció que a veces quería hacerlo todo ella sola y que estaba aprendiendo a delegar. Al final, Beatriz le explicó que había otros tres candidatos y que la llamarían en una semana. Leila salió sin saber si la elegirían, pero con la sensación de haber dado lo mejor de sí misma. Cinco días después, sonó el teléfono.", gl: ["el currículum|السيرة الذاتية", "citar|يحدّد موعدًا", "planchar|يكوي", "la entrevistadora|المُحاوِرة", "reaccionar|يتصرّف / يردّ", "el punto débil|نقطة الضعف", "delegar|يفوّض المهامّ", "el candidato|المرشّح للوظيفة"], q: [["¿Cuánto tiempo llevaba Leila buscando trabajo?", ["Cuatro meses", "Cuatro semanas", "Un año"], 0], ["¿Qué tipo de empresa la llamó?", ["Una escuela", "Una empresa de logística", "Un hospital"], 1], ["¿Cuándo llegó Leila a la entrevista?", ["Veinte minutos tarde", "Justo a la hora", "Veinte minutos antes"], 2], ["¿Qué dijo sobre sus puntos débiles?", ["Que no tenía ninguno", "Que estaba aprendiendo a delegar", "Que no le gustaban los clientes"], 1], ["¿Cuántos candidatos más había?", ["Dos", "Tres", "Cinco"], 1], ["¿Cómo salió Leila de la entrevista?", ["Segura de que la elegirían", "Enfadada con Beatriz", "Sin saberlo, pero satisfecha"], 2]] },

  { id: "r41", lv: "B1", t: "Ibn Battuta, el gran viajero", tar: "ابن بطّوطة الرحّالة الكبير", text: "Ibn Battuta nació en Tánger, en el norte de Marruecos, en el año 1304. A los veintiún años salió de su ciudad para hacer la peregrinación a La Meca. Pensaba volver en poco tiempo, pero su viaje duró casi treinta años. Después de la peregrinación, siguió hacia el este: recorrió Persia, Irak, la costa de África oriental, Anatolia y Asia Central. En la India trabajó varios años como juez para el sultán de Delhi. Más tarde visitó las islas Maldivas y Sri Lanka, y llegó hasta China. Cuando por fin regresó a Marruecos, en 1349, todavía hizo dos viajes más: uno a al-Ándalus, al reino de Granada, y otro al imperio de Malí, cruzando el desierto del Sáhara. Se calcula que recorrió unos ciento veinte mil kilómetros, mucho más que cualquier viajero de su época. El sultán de Marruecos le pidió que contara todo lo que había visto, y un escritor llamado Ibn Yuzayy puso por escrito sus relatos. Ese libro, conocido como la «Rihla», sigue siendo hoy una de las descripciones más valiosas del mundo del siglo XIV.", gl: ["la peregrinación|الحجّ", "recorrer|يجوب / يطوف", "el juez|القاضي", "regresar|يعود", "el reino|المملكة", "el desierto|الصحراء", "poner por escrito|يدوّن كتابةً", "el relato|الحكاية / الرواية"], q: [["¿Dónde nació Ibn Battuta?", ["En La Meca", "En Tánger", "En Granada"], 1], ["¿Por qué salió de su ciudad a los veintiún años?", ["Para trabajar como juez", "Para estudiar en Delhi", "Para hacer la peregrinación"], 2], ["¿Qué trabajo tuvo en la India?", ["Comerciante", "Médico", "Juez"], 2], ["¿Qué viajes hizo después de volver a Marruecos?", ["A Granada y a Malí", "A China y Sri Lanka", "A Persia e Irak"], 0], ["¿Quién escribió sus relatos?", ["El sultán de Delhi", "Ibn Yuzayy", "El propio Ibn Battuta"], 1], ["¿Qué es la «Rihla»?", ["El libro de sus viajes", "El nombre de su ciudad", "Un mapa del Sáhara"], 0]] },

  { id: "r42", lv: "B1", t: "Una semana sin pantallas", tar: "أسبوع بلا شاشات", text: "Todo empezó con una discusión en la cena. Los padres de Sami se quejaban de que sus hijos no levantaban la vista del móvil, y los hijos respondían que ellos también miraban el suyo constantemente. Entonces la madre propuso un reto: una semana entera sin pantallas después de las ocho de la tarde. Los dos primeros días fueron extraños. Sami no sabía qué hacer con las manos y miraba el reloj cada diez minutos. Su hermana pequeña se aburría y protestaba. Pero el tercer día alguien sacó un juego de mesa que llevaba años en un armario, y la casa se llenó de risas. Después vinieron las noches de leer en el sofá, de cocinar juntos y de hablar de cosas de las que nunca habían hablado. Al terminar la semana, votaron si seguir con el reto. Ganó el «sí» por unanimidad, aunque con una condición: los viernes, película en familia. Sami reconoce que ahora duerme mejor y que se concentra más en clase. «Lo raro», dice, «es que no echo de menos el móvil tanto como pensaba».", gl: ["la discusión|الجدال", "quejarse|يشتكي", "levantar la vista|يرفع نظره", "el reto|التحدّي", "la pantalla|الشاشة", "aburrirse|يشعر بالملل", "el juego de mesa|لعبة لوحية", "por unanimidad|بالإجماع"], q: [["¿Cómo empezó todo?", ["Con una discusión en la cena", "Con un castigo del colegio", "Con un móvil roto"], 0], ["¿Qué propuso la madre?", ["Vender los móviles", "Una semana sin pantallas por la noche", "Comprar un juego de mesa"], 1], ["¿Qué cambió el tercer día?", ["Volvieron a usar los móviles", "Fueron al cine", "Sacaron un juego de mesa"], 2], ["¿Qué decidieron al terminar la semana?", ["Dejar el reto", "Seguir con una condición", "Repetirlo solo en verano"], 1], ["¿Qué condición pusieron?", ["Película en familia los viernes", "Móvil solo los sábados", "Televisión durante la cena"], 0], ["¿Qué nota Sami ahora?", ["Que duerme peor", "Que se concentra más en clase", "Que echa mucho de menos el móvil"], 1]] },

  { id: "r43", lv: "B1", t: "Dormir bien, vivir mejor", tar: "نَم جيّدًا تعِش أفضل", text: "Durante años, Marcos pensó que dormir era una pérdida de tiempo. Trabajaba hasta tarde, miraba el móvil en la cama y se levantaba a las seis con tres cafés. Estaba siempre cansado, irritable y con dolor de cabeza, pero lo consideraba normal. Un día, su médico le hizo una pregunta sencilla: «¿Cuántas horas duermes?». Marcos calculó: cinco. El médico le explicó que un adulto necesita entre siete y nueve horas, y que la falta de sueño afecta a la memoria, al estado de ánimo y hasta al sistema inmunitario. Le dio tres consejos: acostarse y levantarse siempre a la misma hora, apagar las pantallas una hora antes de dormir y evitar el café después de las cuatro de la tarde. Marcos no estaba convencido, pero decidió probar durante un mes. Las primeras noches le costó dormirse sin el móvil. Sin embargo, a la tercera semana notó la diferencia: se despertaba sin alarma, tenía más paciencia con sus hijos y rendía mejor en el trabajo. «Pensaba que dormir menos me daba más tiempo», dice ahora. «En realidad, me lo quitaba».", gl: ["una pérdida de tiempo|مضيعة للوقت", "irritable|سريع الانفعال", "la falta de sueño|قلّة النوم", "el estado de ánimo|الحالة المزاجية", "el sistema inmunitario|جهاز المناعة", "acostarse|يخلد إلى النوم", "costar|يصعب على", "rendir|يُنجز بكفاءة"], q: [["¿Qué pensaba Marcos sobre dormir?", ["Que era muy importante", "Que era una pérdida de tiempo", "Que era peligroso"], 1], ["¿Cuántas horas dormía Marcos?", ["Unas cinco", "Unas siete", "Unas nueve"], 0], ["Según el médico, ¿cuántas horas necesita un adulto?", ["Entre cinco y seis", "Entre siete y nueve", "Más de diez"], 1], ["¿Cuál NO es uno de los consejos del médico?", ["Apagar las pantallas una hora antes", "Evitar el café por la tarde", "Hacer deporte antes de dormir"], 2], ["¿Cuándo notó la diferencia?", ["La primera noche", "A la tercera semana", "Después de un año"], 1], ["¿Qué concluye Marcos al final?", ["Que dormir menos le quitaba tiempo", "Que el café no le afecta", "Que necesita dormir diez horas"], 0]] },

  /* ---------- B2 ---------- */
  { id: "r44", lv: "B2", t: "Un huerto en el solar abandonado", tar: "بستان في الأرض المهجورة (خبر صحفي)", text: "MURCIA. Lo que hace un año era un solar lleno de escombros es hoy un huerto de dos mil metros cuadrados con tomates, pimientos, habas y un pequeño invernadero. El proyecto, impulsado por la Asociación Vecinal Raíces del barrio de Los Almendros, reúne cada semana a más de sesenta vecinos. «Al principio nadie creía que fuera posible», explica Dolores Martín, presidenta de la asociación. «El Ayuntamiento nos cedió el terreno por cinco años y lo demás lo hemos hecho entre todos». Cada familia dispone de una parcela de veinte metros cuadrados a cambio de dedicar unas horas al mes a las tareas comunes: el riego, el compost y el mantenimiento de los caminos. Para Ahmed Benkirane, jubilado de sesenta y ocho años, el huerto ha supuesto mucho más que verduras frescas. «Aquí he conocido a vecinos con los que llevaba diez años compartiendo ascensor sin hablar», comenta. Los organizadores destacan también el valor educativo: tres colegios de la zona visitan el huerto cada trimestre, y los alumnos aprenden de dónde viene la comida y cuánta agua cuesta producirla. Durante el verano, las altas temperaturas obligaron a instalar un sistema de riego por goteo, financiado con una venta de plantas, y en octubre desaparecieron varias herramientas. Aun así, la asociación ya trabaja en una segunda fase: un espacio con mesas y sombra donde celebrar talleres y meriendas vecinales. «Un barrio que cultiva junto es un barrio que se cuida», resume Martín.", gl: ["el solar|قطعة أرض خالية", "los escombros|الأنقاض", "el invernadero|البيت الزراعي المحمي", "ceder|يمنح حقّ الاستخدام", "la parcela|قطعة الأرض الصغيرة", "el riego por goteo|الريّ بالتنقيط", "el trimestre|الفصل الدراسي", "la merienda|وجبة خفيفة بعد الظهر"], q: [["¿Qué había antes en el terreno del huerto?", ["Un parque", "Un solar con escombros", "Un colegio"], 1], ["¿Por cuánto tiempo cedió el Ayuntamiento el terreno?", ["Cinco años", "Diez años", "Un año"], 0], ["¿Qué deben hacer las familias a cambio de su parcela?", ["Pagar un alquiler", "Vender verduras", "Dedicar horas a tareas comunes"], 2], ["¿Qué destaca Ahmed Benkirane del huerto?", ["Que ha conocido a sus vecinos", "Que ahorra dinero", "Que las verduras son más grandes"], 0], ["¿Cómo financiaron el riego por goteo?", ["Con dinero del Ayuntamiento", "Con una venta de plantas", "Con una cuota mensual"], 1], ["¿Qué problema tuvieron en octubre?", ["Se secaron las plantas", "Cerró el huerto", "Desaparecieron herramientas"], 2]] },

  { id: "r45", lv: "B2", t: "Averroes, el sabio de Córdoba", tar: "ابن رشد عالِم قرطبة", text: "Abu al-Walid Muhammad ibn Rushd, conocido en Europa como Averroes, nació en Córdoba en 1126, en el seno de una familia de jueces. Siguiendo la tradición familiar, estudió derecho islámico, pero también medicina, matemáticas, astronomía y filosofía, en una ciudad que todavía era uno de los grandes centros intelectuales del Mediterráneo. Fue juez en Sevilla y más tarde juez principal de Córdoba, y ejerció como médico del califa almohade. Su obra médica más conocida, el «Kitab al-Kulliyyat», traducida al latín como «Colliget», fue durante siglos un manual de referencia en las universidades europeas. Sin embargo, su fama se debe sobre todo a sus comentarios sobre Aristóteles. Averroes dedicó gran parte de su vida a explicar, resumir y discutir las obras del filósofo griego, hasta el punto de que en la Europa medieval se le llamaba «el Comentador». Defendió que la razón y la revelación no se contradicen, sino que conducen a la misma verdad por caminos distintos. Sus ideas no siempre fueron bien recibidas: en 1195 cayó en desgracia, sus libros fueron prohibidos y se le desterró a Lucena, aunque poco después fue rehabilitado. Murió en Marrakech en 1198 y sus restos fueron trasladados a Córdoba, donde hoy una estatua lo recuerda junto a la antigua muralla. Pensadores cristianos y judíos de los siglos siguientes, como Tomás de Aquino o Maimónides, leyeron y discutieron su obra, y a través de ella la filosofía griega volvió a circular por Europa.", gl: ["en el seno de|في وسط / في أحضان", "el derecho|الفقه / القانون", "ejercer|يمارس مهنة", "el manual de referencia|المرجع الأساسي", "la revelación|الوحي", "caer en desgracia|يسقط من حُظوة الحاكم", "desterrar|يَنفي", "los restos|الرُّفات"], q: [["¿A qué se dedicaba la familia de Averroes?", ["A la medicina", "A la justicia", "Al comercio"], 1], ["¿Qué era el «Colliget»?", ["Un comentario sobre Aristóteles", "Una obra de astronomía", "Su obra médica traducida al latín"], 2], ["¿Por qué lo llamaban «el Comentador» en Europa?", ["Por sus comentarios sobre Aristóteles", "Por su trabajo como juez", "Por sus discursos públicos"], 0], ["¿Qué defendía Averroes sobre la razón y la revelación?", ["Que se oponen siempre", "Que conducen a la misma verdad", "Que la razón es superior"], 1], ["¿Qué le ocurrió en 1195?", ["Fue nombrado califa", "Fue desterrado a Lucena", "Murió en Marrakech"], 1], ["¿Dónde murió?", ["En Córdoba", "En Sevilla", "En Marrakech"], 2]] },

  { id: "r46", lv: "B2", t: "Un sábado en el ropero solidario", tar: "سبت في مشغل الملابس الخيري", text: "Cada sábado a las nueve, Fátima abre la persiana de un local pequeño en el barrio de Lavapiés, en Madrid. Dentro hay estanterías llenas de abrigos, zapatos infantiles y mantas, donados por vecinos y ordenados por tallas. Es el ropero solidario de una asociación de barrio que ella coordina desde hace cuatro años junto a una docena de voluntarios. Cuando emigró desde Marruecos, hace quince años, pasó un invierno muy duro, y recuerda a la mujer que le dio un abrigo y un plato de sopa sin pedirle nada a cambio. «Me prometí que, cuando pudiera, haría lo mismo», cuenta. El funcionamiento es sencillo: el lunes se recogen las donaciones, el miércoles se lavan y clasifican, y el sábado se atiende a las familias con cita previa. Los voluntarios insisten en un detalle esencial: la ropa se expone como en una tienda, con perchas y espejos, y cada persona elige lo que quiere. «La dignidad también se cuida en los detalles», explica Fátima. Entre los voluntarios hay estudiantes, jubilados, una peluquera que ofrece cortes de pelo gratuitos una vez al mes y un sastre que arregla las prendas que llegan rotas. El mayor desafío no es la falta de ropa, sino el exceso: a veces reciben más de lo que pueden almacenar. Al cerrar, Fátima apaga las luces. «Nunca sabes quién va a cruzar esa puerta», dice. «Pero sabes que se irá con algo más que ropa».", gl: ["la persiana|الستار المعدني للمحلّ", "la estantería|الرفوف", "la talla|المقاس", "el ropero solidario|مشغل الملابس الخيري", "la cita previa|الموعد المسبق", "la percha|علّاقة الملابس", "el sastre|الخيّاط", "la prenda|قطعة الملابس"], q: [["¿Desde cuándo coordina Fátima el ropero?", ["Desde hace cuatro años", "Desde hace quince años", "Desde hace un año"], 0], ["¿Por qué decidió Fátima hacerse voluntaria?", ["Porque buscaba trabajo", "Porque alguien la ayudó en un invierno difícil", "Porque le gusta la moda"], 1], ["¿Qué se hace los miércoles?", ["Se recogen donaciones", "Se atiende a las familias", "Se lava y clasifica la ropa"], 2], ["¿Por qué exponen la ropa como en una tienda?", ["Para venderla más cara", "Porque lo exige la ley", "Para cuidar la dignidad de las personas"], 2], ["¿Cuál es el mayor desafío del ropero?", ["La falta de ropa", "El exceso de donaciones", "La falta de voluntarios"], 1], ["¿Qué hace la peluquera voluntaria?", ["Arregla prendas rotas", "Lava la ropa", "Ofrece cortes de pelo gratuitos"], 2]] },

  { id: "r47", lv: "B2", t: "La ciudad que pedalea", tar: "المدينة التي تركب الدرّاجة", text: "Hace apenas una generación, la bicicleta se consideraba en muchas ciudades un juguete o, como mucho, un vehículo para quienes no podían pagar un coche. Ciudades tan distintas como Sevilla, Bogotá o Ciudad de México han invertido en carriles bici, aparcamientos seguros y sistemas de alquiler público. Las razones son varias. La primera es ambiental: el transporte es una de las principales fuentes de contaminación urbana, y cada trayecto en bicicleta sustituye a un trayecto en coche. La segunda es económica: mantener una bicicleta cuesta una fracción de lo que cuesta un vehículo, sin contar el combustible ni el aparcamiento. La tercera es sanitaria: media hora de pedaleo diario reduce el riesgo de enfermedades cardiovasculares. Bogotá ofrece un ejemplo singular: desde los años setenta, cada domingo cierra más de cien kilómetros de avenidas al tráfico para que la ciudadanía los recorra en bicicleta, en patines o a pie. Sin embargo, el cambio no está libre de conflictos. Peatones que se sienten invadidos, conductores que no respetan la distancia de seguridad y ciclistas que se saltan los semáforos conviven en un espacio que todavía se está redefiniendo. Los urbanistas coinciden en que la solución pasa por infraestructuras bien diseñadas y, sobre todo, por una cultura de respeto mutuo que no se construye en un día. Mientras tanto, cada mañana más personas descubren que llegar al trabajo pedaleando no solo es posible, sino también agradable.", gl: ["el carril bici|مسار الدرّاجات", "invertir|يستثمر", "el trayecto|المشوار / الرحلة القصيرة", "una fracción de|جزء صغير من", "el combustible|الوقود", "cardiovascular|قلبي وعائي", "el peatón|أحد المُشاة", "saltarse un semáforo|يتجاوز الإشارة الحمراء"], q: [["¿Cómo se veía la bicicleta hace una generación?", ["Como un vehículo moderno", "Como un juguete o un vehículo para quien no podía pagar un coche", "Como un deporte de élite"], 1], ["¿Cuál es la razón económica que menciona el texto?", ["Mantener una bicicleta cuesta una fracción de lo que cuesta un coche", "Las ciudades pagan por usar la bicicleta", "El combustible es gratis"], 0], ["¿Qué hace Bogotá cada domingo?", ["Prohíbe las bicicletas", "Cierra avenidas al tráfico", "Regala bicicletas"], 1], ["¿Desde cuándo existe esa iniciativa en Bogotá?", ["Desde el año 2000", "Desde hace una generación", "Desde los años setenta"], 2], ["¿Qué conflicto menciona el texto?", ["Falta de bicicletas", "Peatones que se sienten invadidos", "Precio alto del alquiler"], 1], ["Según los urbanistas, ¿qué hace falta además de infraestructuras?", ["Más coches", "Multas más altas", "Una cultura de respeto mutuo"], 2]] },

  /* ---------- C1 ---------- */
  { id: "r48", lv: "C1", t: "Elogio de la atención", tar: "في مديح الانتباه (مقال رأي)", text: "Hay un gesto que repetimos decenas de veces al día sin apenas darnos cuenta: desbloquear el teléfono para comprobar si ha pasado algo. Casi nunca ha pasado nada. Y, sin embargo, volvemos a hacerlo diez minutos después, como quien abre la nevera sabiendo que está vacía. No pretendo sumarme al coro de quienes demonizan la tecnología; sería hipócrita escribir esta columna en un ordenador y afirmar luego que las pantallas son el enemigo. Lo que me inquieta no es la herramienta, sino lo que estamos dejando de hacer mientras la miramos. La atención es, probablemente, el recurso más valioso que poseemos, y lo estamos regalando a cambio de nada. Las empresas que diseñan estas aplicaciones lo saben mejor que nosotros: cada notificación, cada desplazamiento infinito, cada «te puede interesar» está calculado para retenernos un segundo más. No es una conspiración; es un modelo de negocio. Lo preocupante es que hemos aceptado las reglas sin leerlas. Pienso en mi abuelo, que podía pasar una tarde entera observando cómo crecían sus tomates, o en los artesanos que dedicaban meses a una sola pieza. No eran personas más virtuosas que nosotros; simplemente vivían en un mundo que no competía por sus ojos a cada instante. Recuperar esa capacidad de permanecer en una sola cosa exige hoy un esfuerzo consciente, casi una disciplina. Algunos la buscan en la lectura en papel, otros en una caminata sin auriculares, otros en el silencio de la oración. Quizá el gesto más revolucionario de nuestra época no sea protestar ni innovar, sino algo mucho más humilde: terminar lo que empezamos sin mirar el teléfono. Dejar el móvil en otra habitación durante la cena no cambiará el mundo, pero tal vez cambie la conversación. Y las conversaciones, a la larga, son lo que cambia el mundo.", gl: ["desbloquear|يفتح قفل الهاتف", "sumarse al coro|ينضمّ إلى من يردّدون الرأي نفسه", "demonizar|يصوّر شيئًا كشرّ مطلق", "inquietar|يُقلِق", "el desplazamiento infinito|التمرير اللامتناهي", "retener|يُبقي / يستبقي", "el artesano|الحِرفيّ", "a la larga|على المدى الطويل"], q: [["¿Qué gesto describe el autor al principio?", ["Abrir la nevera", "Escribir una columna", "Desbloquear el teléfono para ver si ha pasado algo"], 2], ["¿Cuál es la postura del autor respecto a la tecnología?", ["La considera el enemigo", "No la demoniza, pero le preocupa lo que dejamos de hacer", "La defiende sin reservas"], 1], ["Según el texto, ¿qué buscan las aplicaciones con cada notificación?", ["Retenernos un segundo más", "Informarnos mejor", "Ahorrarnos tiempo"], 0], ["¿Por qué menciona el autor a su abuelo?", ["Porque era más virtuoso que nosotros", "Porque no sabía usar el teléfono", "Porque vivía en un mundo que no competía por su atención"], 2], ["¿Qué propone el autor como gesto «revolucionario»?", ["Protestar contra las empresas", "Terminar lo que empezamos sin mirar el teléfono", "Innovar con nuevas aplicaciones"], 1], ["Según la última frase, ¿qué cambia el mundo a la larga?", ["Las conversaciones", "Las notificaciones", "Las revoluciones"], 0]] },

  { id: "r49", lv: "C1", t: "La Alhambra: agua, luz y palabra", tar: "قصر الحمراء: ماء ونور وكلمة", text: "Sobre una colina rojiza que domina Granada se alza la Alhambra, el conjunto palaciego mejor conservado del mundo islámico medieval y uno de los monumentos más visitados de Europa. Su nombre procede del árabe «al-Qal'a al-Hamra», «la fortaleza roja», por el color de sus muros al atardecer. Aunque existían construcciones anteriores, fue la dinastía nazarí, fundada en 1238 por Muhammad ibn al-Ahmar, la que la convirtió en ciudad palatina. Los palacios que hoy admiramos se levantaron sobre todo en el siglo XIV, durante los reinados de Yusuf I y Muhammad V, en un reino pequeño y amenazado que, sin embargo, alcanzó un refinamiento artístico extraordinario. La Alhambra es, ante todo, un tratado sobre el agua. Una acequia tomada del río Darro la recorre entera: alimenta fuentes, albercas y canales, refresca los patios y llena de sonido los jardines del Generalife, la finca de recreo de los sultanes. En el célebre Patio de los Leones, doce figuras de mármol sostienen una fuente cuyo sistema hidráulico sigue asombrando a los ingenieros. La luz es el segundo material. Los arquitectos nazaríes no construyeron con mármol macizo, sino con yeso, madera y cerámica, materiales humildes que tallaron hasta convertirlos en encajes. Las celosías filtran el sol, las bóvedas de mocárabes parecen gotear desde el techo y los zócalos de azulejos repiten patrones geométricos que los matemáticos estudian hoy con asombro. Y, por último, la palabra. Los muros están cubiertos de inscripciones: poemas, alabanzas y, repetido cientos de veces, el lema de la dinastía, «No hay vencedor sino Dios». Tras la conquista cristiana de 1492, el conjunto fue respetado en gran medida, y en 1984 la UNESCO lo declaró Patrimonio de la Humanidad. Más de dos millones de personas lo visitan cada año y comprueban que, siete siglos después, el agua sigue cantando.", gl: ["la colina|التلّ", "palaciego|قصريّ", "la dinastía|السلالة الحاكمة", "la acequia|الساقية", "la alberca|البِركة / الحوض", "la celosía|المشربية", "los mocárabes|المقرنصات", "el lema|الشعار"], q: [["¿De dónde procede el nombre «Alhambra»?", ["Del nombre de su fundador", "Del color rojo de sus muros", "Del río que la rodea"], 1], ["¿Cuándo se levantaron la mayoría de los palacios actuales?", ["En el siglo XII", "En el siglo XIV", "Después de 1492"], 1], ["¿De dónde se toma el agua que recorre la Alhambra?", ["Del río Darro", "De un pozo del Generalife", "De la lluvia"], 0], ["¿Con qué materiales construyeron principalmente los arquitectos nazaríes?", ["Mármol macizo", "Piedra y hierro", "Yeso, madera y cerámica"], 2], ["¿Qué se repite cientos de veces en los muros?", ["El nombre de Yusuf I", "Un poema de amor", "El lema de la dinastía"], 2], ["¿Qué ocurrió en 1984?", ["Se restauró el Patio de los Leones", "La UNESCO la declaró Patrimonio de la Humanidad", "Se abrió al público por primera vez"], 1]] },

  { id: "r50", lv: "C1", t: "Cuando el trabajo quema", tar: "حين يُنهِك العمل صاحبه", text: "El término «burnout», que podríamos traducir como «síndrome del trabajador quemado», se acuñó en los años setenta para describir el agotamiento que se observaba en profesionales de la salud y la educación. Medio siglo después, la Organización Mundial de la Salud lo reconoce como un fenómeno ligado al trabajo y lo define a partir de tres dimensiones: un cansancio extremo que no desaparece con el descanso, una distancia mental creciente respecto al propio trabajo, a menudo teñida de cinismo, y una sensación de ineficacia que erosiona la confianza. No se trata de una simple mala racha. Quien lo sufre describe una especie de vacío: las tareas que antes le motivaban se vuelven indiferentes y el cuerpo empieza a hablar en forma de insomnio, dolores de cabeza o problemas digestivos. Lo paradójico es que afecta con frecuencia a las personas más comprometidas, aquellas que se exigen mucho y que tardan en pedir ayuda porque interpretan el cansancio como una debilidad personal. Las causas, sin embargo, rara vez son individuales. Los estudios señalan cargas de trabajo desproporcionadas, falta de control sobre las propias tareas, reconocimiento insuficiente y, cada vez más, la imposibilidad de desconectar que han traído los dispositivos móviles. Por eso los especialistas insisten en que la solución no puede limitarse a recomendar ejercicios de respiración o paseos al aire libre, por útiles que sean: hace falta revisar cómo se organizan las empresas. En el plano personal, conviene aprender a reconocer las señales tempranas, establecer límites claros entre el horario laboral y la vida privada, y cultivar espacios que no tengan nada que ver con la productividad, ya sea la familia, la fe, el deporte o una simple caminata sin auriculares. Descansar no es un premio que se gana trabajando más; es una condición para seguir trabajando bien.", gl: ["acuñar un término|يستحدث مصطلحًا", "el agotamiento|الإنهاك", "teñido de|مشوب بـ", "erosionar|يُقوِّض تدريجيًا", "la mala racha|فترة سيّئة عابرة", "comprometido|ملتزم / مُخلص لعمله", "desproporcionado|غير متناسب", "el auricular|سمّاعة الأذن"], q: [["¿Cuándo se acuñó el término «burnout»?", ["En los años setenta", "En los años noventa", "En 2019"], 0], ["¿Cuál NO es una de las tres dimensiones que define la OMS?", ["Cansancio extremo", "Distancia mental respecto al trabajo", "Exceso de entusiasmo"], 2], ["¿A quién afecta con frecuencia, según el texto?", ["A quienes trabajan poco", "A las personas más comprometidas", "A los recién contratados"], 1], ["¿Cómo describe el texto las causas del síndrome?", ["Como principalmente individuales", "Como desconocidas", "Como raramente individuales"], 2], ["¿Qué opinan los especialistas sobre los ejercicios de respiración?", ["Que son la solución completa", "Que son útiles pero insuficientes", "Que son inútiles"], 1], ["¿Qué idea cierra el texto?", ["Descansar es un premio por trabajar más", "Trabajar más evita el cansancio", "Descansar es una condición para trabajar bien"], 2]] },

  /* ---------- C2 ---------- */
  { id: "r51", lv: "C2", t: "Toledo y el oficio de traducir", tar: "طليطلة ومهنة الترجمة", text: "Hay ciudades que deben su fama a una batalla o a un rey; Toledo la debe a un oficio discreto: el de traducir. Durante los siglos XII y XIII, en la ciudad recién incorporada a la corona de Castilla convivían comunidades musulmana, judía y cristiana, y esa coexistencia, no exenta de tensiones, produjo uno de los episodios intelectuales más fecundos de la Edad Media europea. Lo que la historiografía ha llamado «Escuela de Traductores de Toledo» no fue una institución con aulas y estatutos, sino una sucesión de equipos de trabajo que, bajo la protección primero del arzobispo Raimundo y más tarde del rey Alfonso X el Sabio, vertieron al latín y al castellano un caudal inmenso de saber escrito en árabe. Un erudito que dominaba el árabe, con frecuencia un judío o un mozárabe, leía el texto en voz alta y lo traducía oralmente al romance; un clérigo versado en latín lo transcribía a la lengua culta. Así pasaron a Occidente las obras de Aristóteles comentadas por Avicena y Averroes, el «Almagesto» de Ptolomeo, que Gerardo de Cremona tradujo hacia 1175, el álgebra de al-Juarismi y la medicina de Galeno conservada en versiones árabes. No es exagerado afirmar que las universidades de París, Oxford o Bolonia se nutrieron de manuscritos que habían pasado por manos toledanas. Conviene, no obstante, evitar la idealización. Aquella Toledo no era un paraíso de tolerancia, sino una sociedad jerarquizada en la que las minorías vivían bajo condiciones cambiantes, y los propios traductores trabajaban por encargo, con prisas y con errores que los copistas perpetuaron durante siglos. Pero precisamente por eso su legado resulta más valioso: demuestra que la transmisión del conocimiento no exige la perfección ni la armonía absoluta, sino voluntad de escuchar al otro en su propia lengua. En una época en la que los algoritmos traducen en milisegundos, quizá convenga recordar a aquellos hombres que necesitaban meses para un solo libro y que, sin saberlo, estaban tendiendo el puente por el que la ciencia antigua regresó a Europa.", gl: ["el oficio|المِهنة / الحِرفة", "no exenta de|لا تخلو من", "fecundo|مُثمِر", "verter una obra a|ينقل عملًا إلى لغة أخرى", "el caudal|الفيض الغزير", "el erudito|العالِم المتبحّر", "nutrirse de|يتغذّى على", "tender un puente|يمدّ جسرًا"], q: [["¿A qué debe Toledo su fama, según el autor?", ["A una batalla famosa", "A un oficio discreto: la traducción", "A su catedral"], 1], ["¿Qué era en realidad la «Escuela de Traductores»?", ["Una universidad con aulas y estatutos", "Un monasterio", "Una sucesión de equipos de trabajo bajo protección"], 2], ["¿Cómo se traducía normalmente un texto?", ["Directamente del árabe al latín por una sola persona", "Oralmente al romance y luego por escrito al latín", "Del latín al árabe"], 1], ["¿Qué obra tradujo Gerardo de Cremona hacia 1175?", ["El «Almagesto» de Ptolomeo", "El álgebra de al-Juarismi", "Los comentarios de Averroes"], 0], ["¿Qué advierte el autor sobre aquella Toledo?", ["Que era un paraíso de tolerancia", "Que no debe idealizarse", "Que no tuvo importancia real"], 1], ["Según la conclusión, ¿qué exige la transmisión del conocimiento?", ["Perfección y armonía absoluta", "Algoritmos rápidos", "Voluntad de escuchar al otro en su lengua"], 2]] },

  { id: "r52", lv: "C2", t: "Ciudades para el calor", tar: "مدن تواجه الحرّ", text: "Cada verano, los titulares repiten la misma letanía: récord de temperaturas, noches tropicales, alertas sanitarias. Las ciudades del sur de Europa y de América Latina se han convertido en islas de calor: el asfalto absorbe la radiación de día y la devuelve de noche. La respuesta dominante ha sido tecnológica y, en cierto modo, resignada: más aire acondicionado, que consume más energía y expulsa más calor a la calle, en un círculo vicioso que nadie parece dispuesto a romper. Sin embargo, basta pasear por el casco antiguo de Córdoba o de Sevilla para comprobar que hubo un tiempo en que se construía de otra manera. Las calles estrechas y quebradas proyectan sombra sobre sí mismas; los patios interiores, con su fuente y sus plantas, funcionan como pulmones que enfrían el aire por evaporación; los muros gruesos de adobe o de tapial retrasan la entrada del calor hasta que llega la noche; las celosías dejan pasar la brisa, pero no el sol. La arquitectura andalusí desarrolló durante siglos un saber climático que no necesitaba electricidad porque se apoyaba en la física más elemental: la sombra, la masa térmica, el agua y la ventilación cruzada. Resulta irónico que, tras décadas de levantar torres de vidrio, los urbanistas estén redescubriendo estos principios con nombres nuevos, «arquitectura bioclimática» o «refrigeración pasiva», y presentándolos como innovación. No se trata de volver al siglo XII ni de negar los avances técnicos, sino de admitir que el progreso no siempre es lineal y que algunas soluciones del pasado eran, sencillamente, mejores. Algunas ciudades ya actúan: Sevilla extiende toldos sobre sus calles comerciales; Medellín ha plantado corredores verdes que han bajado varios grados la temperatura de algunas avenidas; Barcelona convierte patios escolares en refugios con sombra. Son medidas modestas, pero apuntan en la dirección correcta: adaptar la ciudad al clima. Quizá la lección más profunda sea de humildad. Durante siglos, quienes habitaron estas tierras entendieron que al sol no se le vence, sino que se negocia con él. Nosotros aún estamos aprendiendo a hacerlo.", gl: ["la letanía|اللازمة المتكرّرة", "la isla de calor|جزيرة الحرارة الحضرية", "resignado|مُستسلِم", "el casco antiguo|المدينة القديمة", "quebrado|متعرّج", "el tapial|الطابية (جدار من التراب المدكوك)", "la masa térmica|الكتلة الحرارية", "el toldo|المظلّة القماشية"], q: [["¿Cuál ha sido la respuesta dominante al calor urbano, según el autor?", ["Plantar árboles", "Más aire acondicionado", "Construir patios"], 1], ["¿Qué función cumplen los patios interiores?", ["Decorar la casa", "Almacenar agua para el invierno", "Enfriar el aire por evaporación"], 2], ["¿En qué se apoyaba el saber climático andalusí?", ["En la electricidad", "En la física elemental: sombra, masa térmica, agua y ventilación", "En materiales importados"], 1], ["¿Qué le parece irónico al autor?", ["Que los urbanistas redescubran estos principios y los presenten como innovación", "Que Córdoba sea tan calurosa", "Que el aire acondicionado sea caro"], 0], ["¿Qué ha hecho Medellín?", ["Instalar toldos", "Plantar corredores verdes", "Cerrar avenidas"], 1], ["¿Cuál es la «lección más profunda», según el texto?", ["Que la tecnología siempre gana", "Que hay que vivir como en el siglo XII", "Que al sol no se le vence, sino que se negocia con él"], 2]] },

  { id: "r53", lv: "C2", t: "Carta a mi sobrino en su primer empleo", tar: "رسالة إلى ابن أخي في أوّل عمل له", text: "Querido Yahya: Me cuenta tu madre que el lunes empiezas en la empresa y que no duermes bien. No te preocupes: a tu edad yo tampoco dormía la víspera de nada importante. Permíteme, con el privilegio de las canas, unas palabras que nadie me dijo entonces. Lo primero: no confundas la prisa con la diligencia. Sentirás la tentación de demostrar en una semana lo que vales, de responder a todos los correos en el acto, de quedarte el último para que te vean. La reputación que vale la pena se construye despacio, con trabajos terminados y promesas cumplidas. Lo segundo: aprende los nombres del conserje, de la señora de la limpieza, del técnico de las impresoras. Son quienes sostienen la casa y sabrán si los miras o miras a través de ellos. Hay empleados brillantes que fracasan por soberbia y otros discretos que llegan lejos porque todos quieren trabajar con ellos. Lo tercero, y hablo con conocimiento de causa: un día te equivocarás, con un error caro. No lo escondas ni busques culpables: ve a tu jefe, explícalo y propón una solución. La confianza crece cuando un error se gestiona con honestidad; lo que destruye carreras no es equivocarse, sino mentir. Lo cuarto: cuida tu fe y tu familia como si fueran la parte más importante de tu trabajo, porque lo son. He visto a hombres ganar mucho dinero y perder la cena con sus hijos, el descanso de los viernes, la capacidad de rezar sin mirar el reloj. Que el trabajo te haga mejor persona, no solo mejor profesional; y si notas que te hace peor, ten el valor de cambiar. Y lo último, que quizá sea lo primero: sé agradecido con quien te enseña, con quien te corrige y, por encima de todo, con Allah, que te ha dado inteligencia y manos para servir. El sustento viene de Él; tú pon el esfuerzo y la honradez. Ya me contarás cómo fue el primer día; prometo escucharte sin dar más consejos. Un abrazo de tu tío, Munir", gl: ["la víspera|عشيّة اليوم المهمّ", "las canas|الشيب", "la diligencia|الاجتهاد والعناية", "en el acto|على الفور", "el conserje|بوّاب المبنى", "la soberbia|الكِبر", "con conocimiento de causa|عن تجربة ودراية", "el sustento|الرزق"], q: [["¿Por qué escribe Munir a su sobrino?", ["Porque Yahya se casa", "Porque Yahya empieza su primer empleo", "Porque Yahya se muda de ciudad"], 1], ["¿Qué advierte Munir en su primer consejo?", ["Que no confunda la prisa con la diligencia", "Que responda a todos los correos de inmediato", "Que se quede el último en la oficina"], 0], ["¿Por qué recomienda aprender los nombres del conserje y del técnico?", ["Porque son los jefes", "Porque pueden darle un ascenso", "Porque sostienen la empresa y notan si los miras"], 2], ["Según Munir, ¿qué destruye carreras?", ["Equivocarse", "Mentir", "Pedir ayuda"], 1], ["¿Qué ha visto perder a hombres que ganaban mucho dinero?", ["Su salud física", "La cena con sus hijos y el descanso", "Su casa"], 1], ["¿Qué promete Munir al final?", ["Visitarlo el lunes", "Buscarle otro trabajo", "Escucharlo sin dar más consejos"], 2]] }
]);
